package com.projectdark.mobile;
import com.projectdark.mobile.world.CountessCastleGeometry;
import org.json.*;
import java.util.*;
/** Per-map lives survive leaving/restart. First boss life has zero reward; second activates once. */
public final class CountessCastleRun {
 private JSONObject maps=new JSONObject();
 public void record(String map,List<RuntimeState.Monster> monsters){if(!CountessCastleGeometry.contains(map))return;try{JSONArray rows=new JSONArray();for(RuntimeState.Monster m:monsters)rows.put(new JSONObject().put("id",m.id).put("hp",m.hp).put("mp",m.mp).put("phaseTriggered",m.bossRecovered).put("x",m.isMoving?m.moveTargetX:m.x).put("y",m.isMoving?m.moveTargetY:m.y).put("attack",m.attackElement).put("defense",m.defenseElement));maps.put(map,rows);}catch(JSONException e){throw new IllegalStateException(e);}}
 public void apply(String map,List<RuntimeState.Monster> monsters){JSONArray rows=maps.optJSONArray(map);if(rows==null)return;for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);if(row==null)continue;for(RuntimeState.Monster m:monsters)if(m.id.equals(row.optString("id"))){int hp=row.optInt("hp",-1),mp=row.optInt("mp",-1);if(hp<0||hp>m.maxHp||mp<0||mp>m.maxMp)continue;m.hp=hp;m.mp=mp;m.alive=hp>0;m.bossRecovered=row.optBoolean("phaseTriggered");m.respawnClock=Float.POSITIVE_INFINITY;m.state=m.alive?RuntimeState.Monster.State.IDLE:RuntimeState.Monster.State.RESPAWN;float x=(float)row.optDouble("x",m.x),y=(float)row.optDouble("y",m.y);if(Float.isFinite(x)&&Float.isFinite(y)&&CountessCastleGeometry.inside(map,x,y)){m.x=x;m.y=y;m.moveStartX=m.moveTargetX=x;m.moveStartY=m.moveTargetY=y;}String a=row.optString("attack"),d=row.optString("defense");if(MonsterElementsV258.natural(a)&&MonsterElementsV258.natural(d)){m.attackElement=a;m.defenseElement=d;}}}}
 public boolean revive(RuntimeState s){if(!CountessCastleGeometry.contains(s.currentMapId()))return false;boolean summoned=false;RuntimeState.Monster lady=null,bomb=null;for(RuntimeState.Monster m:s.monsters()){if(CountessCastleMonsters.type(m.id)==12)lady=m;if(CountessCastleMonsters.type(m.id)==13)bomb=m;}if(lady!=null&&lady.alive&&lady.hp<lady.maxHp/2&&!lady.bossRecovered&&bomb!=null&&!bomb.alive){boolean free=!s.blocked(bomb.x,bomb.y)&&Math.hypot(s.player().x-bomb.x,s.player().y-bomb.y)>=50;for(RuntimeState.Monster other:s.monsters())if(other.alive&&Math.hypot(other.x-bomb.x,other.y-bomb.y)<58)free=false;if(free){lady.bossRecovered=true;bomb.hp=bomb.maxHp;bomb.mp=bomb.maxMp;bomb.alive=true;bomb.state=RuntimeState.Monster.State.IDLE;summoned=true;}}RuntimeState.Monster first=null,second=null;for(RuntimeState.Monster m:s.monsters()){if(CountessCastleMonsters.type(m.id)==10)first=m;if(CountessCastleMonsters.type(m.id)==11)second=m;}if(first==null||second==null||first.alive||first.bossRecovered||second.alive)return summoned;first.bossRecovered=true;second.x=first.x;second.y=first.y;second.moveStartX=second.moveTargetX=second.x;second.moveStartY=second.moveTargetY=second.y;second.hp=second.maxHp;second.mp=second.maxMp;second.alive=true;second.state=RuntimeState.Monster.State.IDLE;s.skillEffects().clear(second.id);return true;}
 public JSONObject snapshot(){try{return new JSONObject().put("version",1).put("maps",new JSONObject(maps.toString()));}catch(JSONException e){throw new IllegalStateException(e);}}
 public boolean restore(JSONObject d){if(d==null||d.optInt("version")!=1||d.optJSONObject("maps")==null)return false;try{maps=new JSONObject(d.getJSONObject("maps").toString());return true;}catch(JSONException e){return false;}}
}
